CREATE TABLE IF NOT EXISTS incident_verifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),incident_id UUID NOT NULL REFERENCES incidents(id) ON DELETE RESTRICT,sync_run_id UUID REFERENCES sync_runs(id) ON DELETE RESTRICT,actual_cause TEXT NOT NULL,evidence TEXT NOT NULL CHECK(NULLIF(BTRIM(evidence),'') IS NOT NULL),notes TEXT,verified_by TEXT NOT NULL CHECK(NULLIF(BTRIM(verified_by),'') IS NOT NULL),verified_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS incident_feedback_reports (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),incident_id UUID NOT NULL REFERENCES incidents(id) ON DELETE RESTRICT,sync_run_id UUID REFERENCES sync_runs(id) ON DELETE RESTRICT,category TEXT NOT NULL CHECK(category IN ('DATA','SIGNAL','AI','UI','OTHER')),description TEXT NOT NULL CHECK(NULLIF(BTRIM(description),'') IS NOT NULL),order_codes JSONB NOT NULL DEFAULT '[]'::jsonb,reported_by TEXT NOT NULL CHECK(NULLIF(BTRIM(reported_by),'') IS NOT NULL),status TEXT NOT NULL DEFAULT 'OPEN',reported_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_incident_verifications_incident_time ON incident_verifications(incident_id,verified_at DESC);
CREATE INDEX IF NOT EXISTS idx_incident_feedback_incident_time ON incident_feedback_reports(incident_id,reported_at DESC);
CREATE TRIGGER incident_verifications_immutable BEFORE UPDATE OR DELETE ON incident_verifications FOR EACH ROW EXECUTE FUNCTION reject_immutable_decision_record();
CREATE TRIGGER incident_feedback_immutable BEFORE UPDATE OR DELETE ON incident_feedback_reports FOR EACH ROW EXECUTE FUNCTION reject_immutable_decision_record();
